cat > /app/output/styles.css <<'EOF'
:root {
  --black: #050505;
  --ink: #141018;
  --muted: #6b6472;
  --line: rgba(20, 16, 24, 0.12);
  --purple: #7638fa;
  --magenta: #f335a8;
  --orange: #ff7a00;
  --gold: #ffd166;
  --green: #0f9b72;
  --blue: #2f7cff;
  --cream: #fffaf3;
  --soft-purple: #f3edff;
  --soft-green: #effbf6;
  --white: #ffffff;
  --shadow: 0 24px 80px rgba(24, 16, 40, 0.16);
  --radius-lg: 36px;
  --radius-md: 24px;
  --radius-sm: 16px;
  --shell: 1180px;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  color: var(--ink);
  background: linear-gradient(180deg, #fff 0%, #fff9f2 42%, #fff 100%);
  font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
  overflow-x: hidden;
}

body.menu-open {
  overflow: hidden;
}

img,
svg {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
select {
  font: inherit;
}

.shell {
  width: min(100% - 40px, var(--shell));
  margin-inline: auto;
}

.section-pad {
  padding: 96px 0;
}

.skip-link {
  position: fixed;
  left: 18px;
  top: 12px;
  z-index: 100;
  transform: translateY(-160%);
  border-radius: 999px;
  background: var(--black);
  color: var(--white);
  padding: 12px 18px;
  font-weight: 800;
}

.skip-link:focus {
  transform: translateY(0);
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(255, 255, 255, 0.82);
  backdrop-filter: blur(18px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.5);
}

.nav {
  min-height: 76px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: "Plus Jakarta Sans", Inter, sans-serif;
  font-weight: 800;
  letter-spacing: -0.04em;
  font-size: 1.25rem;
}

.brand-mark {
  width: 34px;
  height: 34px;
  border-radius: 11px;
  background:
    radial-gradient(circle at 70% 20%, #fff 0 8%, transparent 9%),
    linear-gradient(135deg, var(--purple), var(--magenta) 48%, var(--orange));
  box-shadow: 0 12px 30px rgba(118, 56, 250, 0.35);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-links a {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 0 16px;
  color: #312a38;
  font-size: 0.95rem;
  font-weight: 800;
}

.nav-links a:hover,
.nav-links a:focus-visible {
  background: rgba(118, 56, 250, 0.1);
  outline: none;
}

.nav-links .login-link {
  margin-left: 8px;
  background: var(--black);
  color: var(--white);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.16);
}

.menu-toggle {
  display: none;
  width: 48px;
  height: 48px;
  border: 0;
  border-radius: 999px;
  background: var(--black);
  color: var(--white);
  cursor: pointer;
  place-items: center;
  padding: 12px;
}

.menu-toggle span {
  display: block;
  width: 21px;
  height: 2px;
  background: currentColor;
  border-radius: 999px;
  transition: transform 0.2s ease, opacity 0.2s ease;
}

.menu-toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}

.menu-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.menu-toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

.hero {
  position: relative;
  min-height: 760px;
  display: grid;
  align-items: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 78% 24%, rgba(255, 122, 0, 0.28), transparent 24%),
    radial-gradient(circle at 24% 18%, rgba(118, 56, 250, 0.26), transparent 25%),
    radial-gradient(circle at 50% 84%, rgba(243, 53, 168, 0.16), transparent 26%),
    linear-gradient(135deg, #fff 0%, #fff7ed 46%, #f7f0ff 100%);
  z-index: -2;
}

.hero-bg::after {
  content: "";
  position: absolute;
  inset: 18px;
  border-radius: 44px;
  border: 1px solid rgba(255, 255, 255, 0.8);
  background-image: radial-gradient(rgba(5, 5, 5, 0.08) 1px, transparent 1px);
  background-size: 26px 26px;
  mask-image: linear-gradient(90deg, #000, transparent 70%);
  opacity: 0.45;
}

.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 470px;
  align-items: center;
  gap: 70px;
}

.eyebrow {
  margin: 0 0 14px;
  color: var(--magenta);
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-size: 0.8rem;
}

.eyebrow.purple {
  color: var(--purple);
}

.eyebrow.green {
  color: var(--green);
}

.eyebrow.orange {
  color: var(--orange);
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1,
h2 {
  font-family: "Plus Jakarta Sans", Inter, sans-serif;
  letter-spacing: -0.065em;
  line-height: 0.95;
}

h1 {
  max-width: 850px;
  margin-bottom: 26px;
  font-size: clamp(4rem, 8.5vw, 7.9rem);
}

h2 {
  margin-bottom: 22px;
  font-size: clamp(2.45rem, 5vw, 5.1rem);
}

h3 {
  letter-spacing: -0.025em;
  line-height: 1.12;
}

.hero-subtitle {
  max-width: 610px;
  margin-bottom: 34px;
  color: #3e3447;
  font-size: clamp(1.1rem, 2vw, 1.35rem);
}

.hero-actions,
.store-buttons,
.news-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}

.button {
  min-height: 52px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  padding: 0 24px;
  font-weight: 900;
  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.button:hover,
.button:focus-visible,
.store-button:hover,
.store-button:focus-visible,
.carousel-btn:hover,
.carousel-btn:focus-visible {
  transform: translateY(-2px);
