}

.news-head h2 {
  margin-bottom: 0;
}

.carousel-btn {
  width: 48px;
  height: 48px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--white);
  color: var(--black);
  cursor: pointer;
  font-weight: 900;
  box-shadow: 0 12px 28px rgba(24, 16, 40, 0.08);
}

.news-carousel-wrap {
