.thumb-one { background: radial-gradient(circle at 74% 22%, #ffd166, transparent 18%), linear-gradient(135deg, #7638fa, #f335a8); }
.thumb-two { background: radial-gradient(circle at 30% 25%, #fff, transparent 12%), linear-gradient(135deg, #ff7a00, #ffd166 45%, #f335a8); }
.thumb-three { background: radial-gradient(circle at 72% 34%, #2f7cff, transparent 18%), linear-gradient(135deg, #141018, #7638fa); }
.thumb-four { background: radial-gradient(circle at 70% 28%, #effbf6, transparent 16%), linear-gradient(135deg, #0f9b72, #2f7cff); }

.tag-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 18px 2px 14px;
}

.tag-row span {
  border-radius: 999px;
