  color: var(--white);
  background:
    radial-gradient(circle at 84% 18%, rgba(255, 255, 255, 0.28), transparent 18%),
    linear-gradient(135deg, var(--purple), var(--magenta) 48%, var(--orange));
  box-shadow: 0 28px 80px rgba(118, 56, 250, 0.28);
}

.cta-panel h2 {
  margin-bottom: 8px;
  font-size: clamp(2.4rem, 5vw, 4.9rem);
}

.cta-panel p {
  margin-bottom: 0;
  font-size: 1.35rem;
