  .news-controls .text-link {
    width: 100%;
  }

  .cta-download {
    padding-bottom: 72px;
  }

  .store-buttons,
  .store-button {
    width: 100%;
  }

  .footer-bottom {
    gap: 18px;
  }
}

@media (prefers-reduced-motion: reduce) {
